/**
 * Parse a comma-separated list of rights, `all` grants every right
 * @param {string} string
 * @returns {Array<string>} CLI names of the rights
 */
export function parseOauthConsumerRights(string) {
  const rights = string
    .split(',')
    .map((right) => right.trim())
    .filter((right) => right !== '');
  if (rights.includes('all')) {
    return Object.keys(OAUTH_CONSUMER_RIGHTS);
  }
  const unknownRights = rights.filter((right) => OAUTH_CONSUMER_RIGHTS[right] == null);
  if (unknownRights.length > 0) {
    throw new Error(
      `Unknown right(s): ${unknownRights.join(', ')}. Available rights: all, ${Object.keys(OAUTH_CONSUMER_RIGHTS).join(', ')}`,
    );
  }
  return rights;
}

/**
 * Build the rights object expected by the API, every right not listed is set to false
 * @param {Array<string>} rights CLI names of the rights
 * @returns {Record<string, boolean>}
 */
export function toApiRights(rights) {
  return Object.fromEntries(
    Object.entries(OAUTH_CONSUMER_RIGHTS).map(([cliName, apiName]) => [apiName, rights.includes(cliName)]),
  );
}

/**
 * Get the CLI names of the rights granted in a rights object returned by the API
 * @param {Record<string, boolean>} apiRights
 * @returns {Array<string>}
 */
export function fromApiRights(apiRights) {
  return Object.entries(OAUTH_CONSUMER_RIGHTS)
    .filter(([_cliName, apiName]) => apiRights?.[apiName] === true)
    .map(([cliName]) => cliName);
}

